import{_ as i,c as a,o as l,ah as n,at as r,au as o,av as s}from"./chunks/framework.BccSd9fU.js";const f=JSON.parse('{"title":"Jenkins CI/CD 实现","description":"","frontmatter":{},"headers":[],"relativePath":"jenkins-ci-cd.md","filePath":"jenkins-ci-cd.md","lastUpdated":1772185927000}'),t={name:"jenkins-ci-cd.md"};function c(d,e,h,k,p,b){return l(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="jenkins-ci-cd-实现" tabindex="-1">Jenkins CI/CD 实现 <a class="header-anchor" href="#jenkins-ci-cd-实现" aria-label="Permalink to “Jenkins CI/CD 实现”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本项目使用 Jenkins 实现 VitePress 文档站点的自动化 CI/CD 部署流程。当代码推送到远程仓库后，Jenkins 会自动触发构建、打包、Docker 镜像构建和容器部署，实现一键自动化部署。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><ul><li><strong>构建工具</strong>: VitePress 2.0.0-alpha.15</li><li><strong>包管理器</strong>: pnpm</li><li><strong>容器化</strong>: Docker</li><li><strong>Web 服务器</strong>: Nginx (Alpine)</li><li><strong>CI/CD 平台</strong>: Jenkins</li></ul><h2 id="部署流程" tabindex="-1">部署流程 <a class="header-anchor" href="#部署流程" aria-label="Permalink to “部署流程”">​</a></h2><h3 id="_1-代码检出-checkout" tabindex="-1">1. 代码检出 (Checkout) <a class="header-anchor" href="#_1-代码检出-checkout" aria-label="Permalink to “1. 代码检出 (Checkout)”">​</a></h3><ul><li>从 GitHub 仓库 <code>***/vitePress</code> 的 <code>main</code> 分支拉取最新代码</li></ul><h3 id="_2-项目构建-构建项目" tabindex="-1">2. 项目构建 (构建项目) <a class="header-anchor" href="#_2-项目构建-构建项目" aria-label="Permalink to “2. 项目构建 (构建项目)”">​</a></h3><ul><li>使用 Node.js 23.8.0 环境</li><li>配置 pnpm 镜像源（使用国内镜像加速）</li><li>安装项目依赖</li><li>执行 <code>pnpm run docs:build</code> 构建 VitePress 静态文件</li><li>构建产物输出到 <code>docs/.vitepress/dist</code> 目录</li></ul><h3 id="_3-docker-镜像构建-build-docker-image" tabindex="-1">3. Docker 镜像构建 (Build Docker Image) <a class="header-anchor" href="#_3-docker-镜像构建-build-docker-image" aria-label="Permalink to “3. Docker 镜像构建 (Build Docker Image)”">​</a></h3><ul><li>使用 Dockerfile 构建 Docker 镜像</li><li>镜像名称: <code>vitepress</code></li><li>将构建产物和 Nginx 配置打包到镜像中</li></ul><h3 id="_4-容器部署-run-container" tabindex="-1">4. 容器部署 (Run Container) <a class="header-anchor" href="#_4-容器部署-run-container" aria-label="Permalink to “4. 容器部署 (Run Container)”">​</a></h3><ul><li>停止并删除旧容器（如果存在）</li><li>启动新容器，映射端口 <code>8085:80</code></li><li>容器名称: <code>vitepress-container</code></li></ul><h3 id="_5-清理-post-actions" tabindex="-1">5. 清理 (Post Actions) <a class="header-anchor" href="#_5-清理-post-actions" aria-label="Permalink to “5. 清理 (Post Actions)”">​</a></h3><ul><li>清理未使用的 Docker 镜像和资源</li></ul><h2 id="访问地址" tabindex="-1">访问地址 <a class="header-anchor" href="#访问地址" aria-label="Permalink to “访问地址”">​</a></h2><p>部署完成后，可通过以下地址访问：</p><p><a href="https://gukai.top" target="_blank" rel="noreferrer">gukai.top</a></p><h2 id="配置文件说明" tabindex="-1">配置文件说明 <a class="header-anchor" href="#配置文件说明" aria-label="Permalink to “配置文件说明”">​</a></h2><p><img src="'+r+'" alt="CICD效果图"></p><h3 id="jenkinsfile" tabindex="-1">Jenkinsfile <a class="header-anchor" href="#jenkinsfile" aria-label="Permalink to “Jenkinsfile”">​</a></h3><p>定义了完整的 CI/CD 流水线，包括代码检出、构建、Docker 镜像构建和容器部署等步骤。</p><h3 id="dockerfile" tabindex="-1">Dockerfile <a class="header-anchor" href="#dockerfile" aria-label="Permalink to “Dockerfile”">​</a></h3><p>基于 Nginx Alpine 镜像，将 VitePress 构建产物复制到容器中，配置 Nginx 服务。</p><h3 id="nginx-conf" tabindex="-1">nginx.conf <a class="header-anchor" href="#nginx-conf" aria-label="Permalink to “nginx.conf”">​</a></h3><p>Nginx 配置文件，包含：</p><ul><li>SPA 路由支持（<code>try_files</code> 配置）</li><li>Gzip 压缩优化</li><li>静态资源缓存策略</li><li>安全头设置</li></ul><h2 id="场景说明" tabindex="-1">场景说明 <a class="header-anchor" href="#场景说明" aria-label="Permalink to “场景说明”">​</a></h2><p><strong>场景</strong>: 提交代码到远程仓库，自动部署</p><p>当开发者将代码推送到 GitHub 仓库的 <code>main</code> 分支后： github 通过配置的 web-hook 通知 jenkins,Jenkins 检测到代码变更后，通过 github 凭证拉取最新代码</p><ol><li>Jenkins 自动检测到代码变更</li><li>触发构建流水线</li><li>自动完成构建、打包、部署全流程</li><li>无需手动操作，实现真正的自动化部署</li></ol><p><img src="'+o+'" alt="CICD效果图"><img src="'+s+'" alt="CICD效果图"></p>',33)])])}const m=i(t,[["render",c]]);export{f as __pageData,m as default};
